CREATE TABLE IF NOT EXISTS commerce_products (id BIGSERIAL PRIMARY KEY, sku TEXT NOT NULL UNIQUE, title JSONB NOT NULL, price_minor BIGINT NOT NULL CHECK (price_minor >= 0), currency TEXT NOT NULL DEFAULT 'VND', active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS commerce_orders (id BIGSERIAL PRIMARY KEY, external_reference TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','pending_payment','paid','fulfilling','completed','cancelled','refunded')), total_minor BIGINT NOT NULL CHECK (total_minor >= 0), currency TEXT NOT NULL DEFAULT 'VND', items JSONB NOT NULL DEFAULT '[]'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS commerce_payment_events (id BIGSERIAL PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES commerce_orders(id), provider TEXT NOT NULL CHECK (provider = 'dry-run'), event_type TEXT NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, payload_redacted JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS commerce_refund_events (id BIGSERIAL PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES commerce_orders(id), provider TEXT NOT NULL CHECK (provider = 'dry-run'), amount_minor BIGINT NOT NULL CHECK (amount_minor > 0), idempotency_key TEXT NOT NULL UNIQUE, reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS commerce_orders_status_idx ON commerce_orders(status, updated_at DESC);
